function openTextStyleMenu(mode='browse'){const layer=selectedLayer();if(!layer||layer.type!=='text')return;closeTextStyleMenu();const trigger=$('[data-open-style-menu]'),element=document.createElement('div');element.className='text-style-menu';element.setAttribute('role','dialog');element.setAttribute('aria-label',mode==='create'?'Создать стиль':mode==='rename'?'Переименовать стиль':'Стили текста');const current=textStyle(layer);if(mode==='browse'){element.innerHTML=`<div class="text-style-menu-head"><strong>Стили текста</strong><button type="button" data-style-close aria-label="Закрыть">×</button></div><div class="text-style-search"><span aria-hidden="true">⌕</span><input type="search" data-style-search placeholder="Поиск стиля" aria-label="Поиск стиля"></div><div class="text-style-list" role="listbox" aria-label="Стили текста"></div><div class="text-style-menu-foot"><button type="button" data-style-mode="create">＋ Новый стиль</button>${current?'<button type="button" data-style-mode="rename">✎ Переименовать</button>':''}</div>`;}else{element.innerHTML=`<div class="text-style-menu-head"><strong>${mode==='create'?'Новый стиль':'Переименовать стиль'}</strong><button type="button" data-style-close aria-label="Закрыть">×</button></div><form data-style-form><label>Название<input name="name" type="text" maxlength="60" required value="${esc(mode==='rename'?current?.name||'':'')}" placeholder="Название стиля"></label><div class="text-style-form-actions"><button type="button" data-style-mode="browse">Отмена</button><button type="submit" class="primary">${mode==='create'?'Создать':'Сохранить'}</button></div></form>`;}
 document.body.append(element);textStyleMenu={element,trigger,mode,layerId:layer.id};if(mode==='browse')filterTextStyles('');const rect=trigger?.getBoundingClientRect()||{left:innerWidth-320,right:innerWidth-20,top:60,bottom:95},width=Math.min(320,innerWidth-24);element.style.width=width+'px';element.style.left=clamp(rect.right-width,12,innerWidth-width-12)+'px';element.style.top=(rect.bottom+8)+'px';if(rect.bottom+Math.min(element.scrollHeight,440)>innerHeight-12)element.style.top=Math.max(12,rect.top-Math.min(element.scrollHeight,440)-8)+'px';trigger?.setAttribute('aria-expanded','true');if(mode==='browse')element.querySelector('[data-style-search]').focus();else element.querySelector('[name=name]').focus();}
function submitTextStyleMenu(name){if(!textStyleMenu)return;const mode=textStyleMenu.mode,layer=allLayers().find(l=>l.id===textStyleMenu.layerId),current=textStyle(layer),clean=name.trim().slice(0,60);if(!clean)return notify('Укажите название стиля',true);if(mode==='create'&&(doc.textStyles||[]).length>=50)return notify('В макете уже 50 стилей',true);if(!layer)return closeTextStyleMenu();closeTextStyleMenu();commit(()=>{if(mode==='create'){const style={id:'style-'+uid(),name:clean};for(const key of textStyleKeys)style[key]=layer[key]??(key==='lineHeight'?1.25:key==='letterSpacing'?0:['bold','italic','underline','strike'].includes(key)?false:'');doc.textStyles.push(style);layer.styleId=style.id;syncTextStyle(style);}else if(current)current.name=clean;});}
function effectControls(l){const open=strokeOpen(l),shadow=l.shadow;let body=effectSwitch('Обводка','strokeOn',open,glyph.outside);if(open){body+=colorControl('Цвет обводки','stroke',l.stroke||'#333333')+slider('Толщина','strokeWidth',l.strokeWidth||0.4,0.1,10,0.1);if(l.type!=='line')body+=strokePlacement(l);body+=`<p class="visual-label">Штрих</p>${segments('strokeDash',l.strokeDash||'solid',[['solid','Сплошная',glyph.solid],['dashed','Пунктир',glyph.dashed],['dotted','Точки',glyph.dotted]])}`;}body+=effectSwitch('Тень','shadowOn',!!shadow,'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="5" width="12" height="12" rx="2" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M9 20h10V9" fill="none" stroke="currentColor" stroke-width="1.8" opacity=".5"/></svg>');if(shadow)body+=colorControl('Цвет тени','shadow.color',shadow.color||'#000000')+slider('Сдвиг X','shadow.offsetX',shadow.offsetX||0,-20,20,0.5)+slider('Сдвиг Y','shadow.offsetY',shadow.offsetY||0,-20,20,0.5)+slider('Размытие','shadow.blur',shadow.blur??2,0,20,0.5)+slider('Сила тени','shadow.opacity',shadow.opacity??35,0,100,1);return body;}
function applyTextPaint(object,l){if(!object||!l)return;const width=activeStroke(l),align=l.strokeAlign||'center',drawn=align==='outside'?width*2:width;object.set({fontFamily:l.font||'Arial',fontWeight:l.bold?'bold':'normal',fontStyle:l.italic?'italic':'normal',underline:!!l.underline,linethrough:!!l.strike,fill:l.color||'#333333',textAlign:l.align==='justify'?'justify':(l.align||'left'),lineHeight:l.lineHeight||1.25,charSpacing:(Number(l.letterSpacing)||0)*10,fontSize:(l.fontSize||12)*.3528,stroke:width?((/^#[0-9a-fA-F]{6}$/.test(l.stroke)?l.stroke:'#333333')+Math.round(clamp(l.strokeOpacity??100,0,100)/100*255).toString(16).padStart(2,'0')):null,strokeWidth:drawn,strokeDashArray:width?dashArray(l.strokeDash,width):null,paintFirst:align==='outside'?'stroke':'fill',strokeUniform:true,shadow:shadowPaint(l.shadow),dirty:true,objectCaching:false});object.setCoords?.();}
function alignmentIcon(type){const paths={left:'M4 3v18M7 7h12M7 12h8M7 17h12',cx:'M12 3v18M5 7h14M8 12h8M5 17h14',right:'M20 3v18M5 7h12M9 12h8M5 17h12',top:'M3 4h18M7 7v12M12 7v8M17 7v12',cy:'M3 12h18M7 5v14M12 8v8M17 5v14',bottom:'M3 20h18M7 5v12M12 9v8M17 5v12'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="${paths[type]}"/></svg>`;}
function safetyPanel(sec){const guide=sec.cover?(sec.safety||{}):(doc.safety||{}),scope=sec.cover?'cover':'pages';return block('Линии безопасности',`<div class="safety-summary"><div><span class="safety-dot safe"></span>Безопасная зона <strong>${round(guide.safe||0)} мм</strong></div><div><span class="safety-dot bleed"></span>Вылет <strong>${round(guide.bleed||0)} мм</strong></div>${sec.cover?`<div><span class="safety-dot spine"></span>Корешок <strong>${round(guide.spine||0)} мм</strong></div><div><span class="safety-dot gap"></span>Расстав <strong>${round(guide.gap||0)} мм</strong></div>`:''}<button type="button" class="wide safety-open" data-open-safety="${scope}">Настроить линии безопасности →</button></div>`);}
let safetyScope='pages',safetyStart=null,safetyFrame=0;
function safetySize(){return safetyScope==='cover'?(doc.sections.find(s=>s.cover)?.pageSize||doc.pageSize||[210,280]):(doc.pageSize||[210,280]);}
function safetySettings(){return safetyScope==='cover'?(doc.sections.find(s=>s.cover).safety??={}):(doc.safety??={});}
function safetyControl(key,title,help,max){const value=round(safetySettings()[key]||0);return `<div class="safety-control"><div class="safety-control-heading"><strong>${title}</strong><small>${help}</small></div><div class="safety-control-inputs"><input type="range" data-safety-key="${key}" min="0" max="${max}" step="0.5" value="${value}" aria-label="${title}"><label><input type="number" data-safety-key="${key}" min="0" max="${max}" step="0.5" value="${value}" aria-label="${title}, мм"><span>мм</span></label></div></div>`;}
function renderSafetyPreview(){const [w,h]=safetySize(),g=safetySettings(),bleed=Number(g.bleed)||0,safe=Number(g.safe)||0,spine=Number(g.spine)||0,gap=Number(g.gap)||0,cover=safetyScope==='cover';const bx=bleed/w*100,by=bleed/h*100,sx=(bleed+safe)/w*100,sy=(bleed+safe)/h*100;$('#safety-preview').innerHTML=`<div class="safety-preview-title">${cover?'Развёртка обложки':'Типовой разворот страниц'} <span>${round(2*w)} × ${round(h)} мм</span></div><div class="safety-sheet" style="aspect-ratio:${2*w}/${h};--bleed-x:${bx}%;--bleed-y:${by}%;--safe-x:${sx}%;--safe-y:${sy}%;--spine:${spine/(2*w)*100}%;--gap:${gap/(2*w)*100}%"><div class="safety-page"><div class="safety-trim"></div><div class="safety-safe"></div><span>${cover?'Оборотная':'Левая'}</span></div><div class="safety-page"><div class="safety-trim"></div><div class="safety-safe"></div><span>${cover?'Лицевая':'Правая'}</span></div>${cover?'<div class="safety-spine"></div><div class="safety-gap left"></div><div class="safety-gap right"></div>':''}</div><p>Схема показывает расположение линий. На холсте они обновляются при изменении значения.</p>`;$('#safety-legend').innerHTML=`<span><i class="safety-dot bleed"></i>Вылет за линию реза</span><span><i class="safety-dot safe"></i>Область важных элементов</span>${cover?'<span><i class="safety-dot spine"></i>Корешок и расстав</span>':''}`;}
function renderSafetyDialog(){const cover=safetyScope==='cover';$$('#safety-dialog [data-safety-scope]').forEach(b=>{const active=b.dataset.safetyScope===safetyScope;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$('#safety-controls').innerHTML=safetyControl('safe','Безопасная зона','Отступ для текста и важных деталей от линии реза',60)+safetyControl('bleed','Вылет','Фон и изображения продолжаются за линию реза',30)+(cover?safetyControl('spine','Корешок','Центральная часть переплёта',100)+safetyControl('gap','Расстав','Зазор по краям корешка для сгиба и склейки',50):'');renderSafetyPreview();}
function selectSafetyScope(scope){safetyScope=scope;const target=scope==='cover'?doc.sections.find(s=>s.cover):doc.sections.find(s=>!s.cover);if(target){view.section=target.id;view.spread=0;view.side=scope==='cover'?1:0;selected=[];render();}renderSafetyDialog();}
function openSafety(scope){if(preview)return;safetyStart=clone(doc);$('#safety-dialog').showModal();selectSafetyScope(scope);}
function scheduleSafetyScene(){if(safetyFrame)return;safetyFrame=requestAnimationFrame(()=>{safetyFrame=0;renderScene();});}
$('#safety-dialog').addEventListener('input',e=>{const key=e.target.dataset.safetyKey;if(!key)return;const raw=Number(e.target.value);if(!Number.isFinite(raw))return;const g=safetySettings(),[w,h]=safetySize(),limit=Math.min(w,h)/2-1;let max=key==='safe'?Math.min(60,limit-(Number(g.bleed)||0)):key==='bleed'?Math.min(30,limit-(Number(g.safe)||0)):key==='spine'?Math.min(100,w):50;g[key]=round(clamp(raw,0,Math.max(0,max)));$$(`#safety-dialog [data-safety-key="${key}"]`).forEach(input=>{if(input!==e.target||input.type==='range')input.value=g[key];});renderSafetyPreview();scheduleSafetyScene();});
$('#safety-dialog').addEventListener('click',e=>{const tab=e.target.closest('[data-safety-scope]');if(tab)selectSafetyScope(tab.dataset.safetyScope);});
for(const id of ['safety-close','safety-done'])$('#'+id).onclick=()=>$('#safety-dialog').close();
$('#safety-dialog').addEventListener('close',()=>{if(safetyFrame){cancelAnimationFrame(safetyFrame);safetyFrame=0;}if(safetyStart&&JSON.stringify(safetyStart)!==JSON.stringify(doc)){history.push(safetyStart);if(history.length>60)history.shift();future=[];markDirty();render();}safetyStart=null;});
const vignetteDialog=$('#vignette-dialog');
function vignetteLive(key,value,input){const l=selectedLayer();if(!l||l.type!=='grid'||!Number.isFinite(value))return;if(!slide)slide={start:clone(doc)};const grids=section().spreads.flatMap(sp=>sp.pages.flatMap(p=>p.layers)).filter(item=>item.type==='grid');if(key==='minFontSize')value=Math.min(value,l.fontSize);for(const item of grids){item[key]=value;if(key==='min'&&item.max<value)item.max=value;if(key==='max'&&item.min>value)item.min=value;if(key==='fontSize'&&item.minFontSize>value)item.minFontSize=value;if(key==='minPhotoWidth'&&(item.photoWidth??85)<value)item.photoWidth=value;if(key==='photoWidth'&&item.minPhotoWidth>value)item.minPhotoWidth=value;}if(input&&Number(input.value)!==value)input.value=String(value);const paired=key==='min'?'max':key==='max'?'min':key==='fontSize'?'minFontSize':key==='photoWidth'?'minPhotoWidth':key==='minPhotoWidth'?'photoWidth':null;if(paired){const other=$(`#vignette-controls [data-prop="${paired}"]`);if(other)other.value=l[paired];}planner=MasterPlanner(doc,view);plans=planner.plan();vignettePreview();renderScene();}
async function uploadVignetteFont(el){const file=el.files?.[0];el.value='';if(!file)return;if(file.size>1500000)return notify('Шрифт больше 1,5 МБ',true);if((doc.fonts||[]).length>=12)return notify('В макете уже 12 шрифтов',true);const bytes=new Uint8Array(await file.arrayBuffer()),format=fontKind(bytes);if(!format)return notify('Нужен файл TTF или OTF',true);const name=(file.name.replace(/\.(ttf|otf)$/i,'').trim()||'Шрифт').slice(0,60),id='font-'+uid(),dataUrl='data:font/'+format+';base64,'+bytesToBase64(bytes),key=el.dataset.fontTarget||'font';commit(()=>{doc.fonts=[...(doc.fonts||[]),{id,name,dataUrl}];section().spreads.flatMap(sp=>sp.pages.flatMap(p=>p.layers)).filter(item=>item.type==='grid').forEach(item=>item[key]=id);});renderVignetteDialog();}
vignetteDialog.addEventListener('click',e=>{if(e.target.closest('#vignette-close,#vignette-done')){vignetteDialog.close();return;}const tab=e.target.closest('[data-vignette-dialog-tab]');if(tab){vignetteDialogTab=tab.dataset.vignetteDialogTab;renderVignetteDialog();return;}const type=e.target.closest('[data-vignette-type]');if(type){vignetteTextTab=type.dataset.vignetteType;renderVignetteDialog();return;}const color=e.target.closest('[data-color-key]');if(color){openColor(color);return;}const remove=e.target.closest('[data-font-remove]');if(remove){const id=remove.dataset.fontRemove;loadedFonts.delete(id);commit(()=>{doc.fonts=(doc.fonts||[]).filter(font=>font.id!==id);allLayers().forEach(layer=>{if(layer.font===id)layer.font='Arial';if(layer.detailFont===id)layer.detailFont='Arial';});(doc.textStyles||[]).forEach(style=>{if(style.font===id)style.font='Arial';});});renderVignetteDialog();return;}const choice=e.target.closest('[data-choice]');if(!choice)return;const l=selectedLayer(),key=choice.dataset.choice;if(!l)return;if(key==='showDetail'){vignetteTextTab=l.showDetail?'name':'detail';property(key,!l.showDetail);}else if(['bold','italic','underline','strike','detailBold','detailItalic','detailUnderline','detailStrike'].includes(key))property(key,!l[key]);else property(key,choice.dataset.value);renderVignetteDialog();});
